@Override
public synchronized List<SessionSummary> listSummaries() {
    try (var files = Files.list(root)) {
        var result = new ArrayList<SessionSummary>();
        for (Path file : files.filter(candidate -> candidate.getFileName().toString().endsWith(SUFFIX)).toList()) {
            String name = file.getFileName().toString();
            load(name.substring(0, name.length() - SUFFIX.length())).map(SessionSummary::from).ifPresent(result::add);
        }
        return result.stream().sorted(Comparator.comparing(SessionSummary::updatedAt).reversed()).toList();
    } catch (IOException exception) {
        throw storage("cannot list JSONL Session summaries", exception);
    }
